import React, { useEffect, useRef, useState } from "react";
import useWebSocket, { ReadyState } from "react-use-websocket";
import { getAccessToken } from "../../../helpers/authUtils";
import InventoryTable from "../inventory/WholesaleInventoryTable";
import { useNavigate } from "react-router-dom";
import { Loading } from "../../../components";
import useApi from "../../../hooks/useApi";
import wholesalersApi from "../../../api/wholesalers/wholesalersApi";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import InventoryFormModal from "./InventoryFormModal";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Pack Qty", uid: "pack_quantity" },
  { name: "Buying Price", uid: "pack_buying_price" },
  { name: "Selling Price", uid: "pack_selling_price" },
  { name: "Mfd", uid: "manufacture_date" },
  { name: "Units Per Pack", uid: "units_per_pack" },
  { name: "Expiry", uid: "expiry_date" },
  { name: "Expiry Status", uid: "expiry_status" },
  { name: "Actions", uid: "actions" },
];
export default function WholesalerInventoryList() {
  const [openRetailerReceiptFormModal, setopenRetailerReceiptFormModal] =
    useState(false);
  const [userToken, setUserToken] = useState();
  const [retailerReceipt, setRetailerReceipt] = useState();
  // const [retailerReceipts, setRetailerReceipts] = useState([])
  const [loading, setloading] = useState(true);
  const [updated, setUpdated] = useState(false);
  const [itemsToDisplay, setitemsToDisplay] = useState(50);
  const [modalTitle, setmodalTitle] = useState("Add new wholesale inventory");
  const navigate = useNavigate();
  const [wholesalerReceipts, setwholesalerReceipts] = useState([]);

  const [data, setdata] = useState(wholesalerReceipts);
  const [errors, seterrors] = useState();

  useEffect(() => {
    setUserToken(getAccessToken());
  }, []);

  useEffect(() => {
    setdata(wholesalerReceipts);
  }, [wholesalerReceipts]);

  const wholesaleReceiptsApi = useApi(wholesalersApi.wholesaleStaffAction);

  const getReceipts = async () => {
    seterrors(null);
    await wholesaleReceiptsApi.request({
      action: "GetWholesalerReceipts",
    });
  };

  useEffect(() => {
    getReceipts();
  }, []);

  useEffect(() => {
    console.log("wholesaleReceiptsApi.data", wholesaleReceiptsApi.data);
    if (
      wholesaleReceiptsApi.data &&
      wholesaleReceiptsApi.data.errors &&
      wholesaleReceiptsApi.data.errors.length
    ) {
      seterrors(wholesaleReceiptsApi.data.errors);
    } else {
      setdata(wholesaleReceiptsApi.data);
    }
  }, [wholesaleReceiptsApi.data]);

  const { readyState, sendJsonMessage } = useWebSocket(
    userToken ? `ws://127.0.0.1:8000/wholesalers/inventory/staff/` : null,
    {
      queryParams: {
        token: userToken ? userToken : "",
      },
      onOpen: () => {
        console.log("Connected!");
      },
      onClose: () => {
        console.log("Disconnected!");
      },
      // onMessage handler
      onMessage: (e) => {
        console.log("resp", e);
        console.log("data", JSON.parse(e.data));
        setloading(false);
        setwholesalerReceipts(JSON.parse(e.data));
      },
    }
  );

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      getReceipts();

      // Simulating an API failure in the polling callback
      //   const shouldFail = Math.random() < 0.2; // Simulate 20% chance of API failure

      //   if (shouldFail) {
      //     setIsPollingEnabled(false);
      //     console.log("Polling failed. Stopped polling.");
      //   }
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 5000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getReceipts]);
  const connectionStatus = {
    [ReadyState.CONNECTING]: "Connecting",
    [ReadyState.OPEN]: "Open",
    [ReadyState.CLOSING]: "Closing",
    [ReadyState.CLOSED]: "Closed",
    [ReadyState.UNINSTANTIATED]: "Uninstantiated",
  }[readyState];

  const handleEditAction = (item) => {
    setopenRetailerReceiptFormModal(true);

    // setUpdated(false)

    setRetailerReceipt(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenRetailerReceiptFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new wholesale inventory");
    setRetailerReceipt(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/retailers/inventory/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/retailers/inventory/delete/${item.id}`);
  };
  const handleFilter = (e) => {
    console.log("filter", e);

    const search_param = e;

    if (search_param && search_param !== "") {
      setdata(
        wholesalerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(wholesalerReceipts);
      console.log("receipts", wholesalerReceipts);
      // dispatch()
    }
  };

  return (
    <div>
      {errors && (
        <div>
          {errors.map((error) => {
            return (
              <p className="font-bold text-red-500 text-medium">{error}</p>
            );
          })}
        </div>
      )}

      {openRetailerReceiptFormModal && (
        <InventoryFormModal
          ismodalOpen={openRetailerReceiptFormModal}
          setisModalOpen={setopenRetailerReceiptFormModal}
          inventoryToEdit={retailerReceipt}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      {data ? (
        <InventoryTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
          itemsToDisplay={itemsToDisplay}
          setitemsToDisplay={setitemsToDisplay}
        />
      ) : (
        <Loading loading={loading} />
      )}
    </div>
  );
}
